package storage;
import model.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import repository.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
class JsonStoreTest {
 @TempDir Path temp;
 @Test void missingCollectionsInitializeAndSurviveRecreation() throws Exception {JsonStore first=new JsonStore(temp);assertTrue(first.users().isEmpty());assertTrue(first.lost().isEmpty());assertTrue(first.found().isEmpty());new JsonUserRepository(first).create(user("sam_user"));assertEquals("sam_user",new JsonStore(temp).users().getFirst().getUsername());assertTrue(Files.exists(temp.resolve("users.json")));}
 @Test void duplicateUsernameIsRejectedWithoutCaseSensitivity(){JsonUserRepository repo=new JsonUserRepository(new JsonStore(temp));repo.create(user("student1"));assertThrows(IllegalArgumentException.class,()->repo.create(user("STUDENT1")));}
 @Test void concurrentRegistrationsCannotDuplicateUsername()throws Exception{JsonUserRepository repo=new JsonUserRepository(new JsonStore(temp));ExecutorService pool=Executors.newFixedThreadPool(8);try{List<Callable<Boolean>> calls=new ArrayList<>();for(int i=0;i<16;i++)calls.add(()->{try{repo.create(user("same-user"));return true;}catch(IllegalArgumentException e){return false;}});long created=pool.invokeAll(calls).stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count();assertEquals(1,created);assertEquals(1,new JsonStore(temp).users().size());}finally{pool.shutdownNow();}}
 @Test void reportsSupportCreateReadUpdateDeleteAndPersist() {JsonReportRepository repo=new JsonReportRepository(new JsonStore(temp));Report report=report("owner-a","LOST","item");repo.create(report);assertEquals("item",repo.find("LOST",report.getId()).orElseThrow().getTitle());assertEquals(1,repo.mine("LOST","owner-a").size());report.setTitle("updated");assertTrue(repo.update(report));assertEquals("updated",repo.find("LOST",report.getId()).orElseThrow().getTitle());assertEquals("updated",new JsonReportRepository(new JsonStore(temp)).list("LOST").getFirst().getTitle());assertTrue(repo.delete("LOST",report.getId()));assertTrue(repo.list("LOST").isEmpty());}
 @Test void validBackupRestoresMalformedFile() throws Exception {Path f=temp.resolve("users.json");Files.writeString(f,"{broken");Files.writeString(temp.resolve("users.json.bak"),"[{\"id\":\"1\",\"username\":\"backup-user\",\"email\":\"b@x.edu\",\"role\":\"STUDENT\",\"passwordHash\":\"a:b\"}]");assertEquals("backup-user",new JsonStore(temp).users().getFirst().getUsername());assertTrue(Files.readString(f).startsWith("["));}
 @Test void malformedFileWithoutBackupIsReportedAndPreserved() throws Exception {Path f=temp.resolve("users.json");Files.writeString(f,"{broken");assertThrows(IllegalStateException.class,()->new JsonStore(temp).users());assertEquals("{broken",Files.readString(f));}
 private User user(String name){return new User(UUID.randomUUID().toString(),name,name+"@example.edu","STUDENT","salt:hash");}
 private Report report(String owner,String type,String title){Report r=new Report();r.setId(UUID.randomUUID().toString());r.setOwnerId(owner);r.setType(type);r.setTitle(title);r.setCategory("Other");r.setDescription("");r.setLocation("Library");r.setReportDate(LocalDate.now());r.setStatus(type);r.setCreatedAt(Instant.now());r.setUpdatedAt(Instant.now());return r;}
}